import unittest

from app.billing import apply_discount


class TestApplyDiscountRaises(unittest.TestCase):
    """Asserts the bug instead of the contract — the wrong shape of repro."""

    def test_missing_rate_raises(self):
        with self.assertRaises(TypeError):
            apply_discount(100.0, None)


if __name__ == "__main__":
    unittest.main()
